const tabId = 343605414;
const pageData = await browserjs(tabId, () => {
  // Let's find all text and links in the content area
  const content = document.querySelector('.main-content') || document.querySelector('#main-content') || document.querySelector('main') || document.body;

  // Let's get all headings and links
  const items = Array.from(content.querySelectorAll('a, h1, h2, h3, h4, p, li')).map(el => ({
    tag: el.tagName,
    text: el.innerText.trim(),
    href: el.href || null
  })).filter(x => x.text.length > 0);

  return items;
});

console.log("Total items:", pageData.length);
// Let's filter for relevant content (not header/footer/language selector)
const relevant = pageData.filter(x => 
  !x.text.includes("Select Language") && 
  !x.text.includes("Terms & Conditions") && 
  !x.text.includes("Privacy Policy") &&
  !x.text.includes("About the MTA") &&
  !x.text.includes("Doing Business")
);
console.log(JSON.stringify(relevant.slice(0, 100), null, 2));

